SELECT gen_random_uuid()::text, 'formula', '$I = \frac{V}{R_{body}}$', 'Shock Current Through the Body', '$I = \frac{V}{R_{body}};\qquad \approx 1\ \text{mA felt},\ 10\text{–}20\ \text{mA can''t let go},\ 50\text{–}100\ \text{mA may cause fibrillation}$', '$\text{A}$', 'Current, not voltage, is what harms: it depends on the voltage and on the path''s resistance.', '[{"symbol":"$V$","meaning":"touch voltage","unit":"$\\text{V}$"},{"symbol":"$R_{body}$","meaning":"body resistance: about 1 kΩ wet, 100 kΩ or more dry skin","unit":"$\\Omega$"}]'::jsonb, 'Wet skin turns a harmless 120 V touch into a deadly 120 mA.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Basic Occupational Safety & Health' AND t."subject" = 'ESAS' AND s."normKey" = 'electrical safety and lockout/tagout' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Basic Occupational Safety & Health' AND t."subject" = 'ESAS'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
