SELECT gen_random_uuid()::text, 'formula', '$I_B = \frac{0.116}{\sqrt{t}}$', 'Tolerable Body Current (Dalziel)', '$I_B = \frac{k}{\sqrt{t}};\qquad k = 0.116 \text{ (50 kg)},\ 0.157 \text{ (70 kg)};\ 0.03 \le t \le 3\ \text{s}$', '$\text{A}$', 'The most current a body survives without ventricular fibrillation, for a short shock (IEEE 80).', '[{"symbol":"$t$","meaning":"shock duration","unit":"$\\text{s}$"}]'::jsonb, 'Faster fault clearing allows more current: halving the time raises the limit by √2.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Basic Occupational Safety & Health' AND t."subject" = 'ESAS' AND s."normKey" = 'electrical safety and lockout/tagout' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Basic Occupational Safety & Health' AND t."subject" = 'ESAS'
