SELECT gen_random_uuid()::text, 'formula', '$E_{touch} = (1000 + 1.5C_s\rho_s)\frac{0.116}{\sqrt t}$', 'Tolerable Touch and Step Voltages', '$E_{touch} = (1000 + 1.5\,C_s\rho_s)\frac{0.116}{\sqrt{t}},\qquad E_{step} = (1000 + 6\,C_s\rho_s)\frac{0.116}{\sqrt{t}}$', '$\text{V}$', 'The voltages a 50 kg person can safely bridge in a substation during a ground fault (IEEE 80).', '[{"symbol":"$\\rho_s$","meaning":"resistivity of the surface layer (crushed rock)","unit":"$\\Omega\\cdot\\text{m}$"},{"symbol":"$C_s$","meaning":"surface-layer derating factor (1 with no layer)","unit":null},{"symbol":"$t$","meaning":"shock duration","unit":"$\\text{s}$"}]'::jsonb, 'A crushed-rock layer raises both limits a lot: that is why substations are covered in gravel.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Basic Occupational Safety & Health' AND t."subject" = 'ESAS' AND s."normKey" = 'electrical safety and lockout/tagout' AND s."active"), NULL, false, 'PENDING', now(), now()
