SELECT gen_random_uuid()::text, 'formula', '$RWL$', 'NIOSH Lifting Equation', '$RWL = 23\ \text{kg} \times \frac{25}{H} \times (1 - 0.003|V - 75|) \times \left(0.82 + \frac{4.5}{D}\right) \times (1 - 0.0032A) \times FM \times CM$', '$\text{kg}$', 'The recommended weight limit for a lift: 23 kg cut down by each poor condition.', '[{"symbol":"$H$","meaning":"horizontal distance of the load from the ankles (≥ 25)","unit":"$\\text{cm}$"},{"symbol":"$V$","meaning":"height of the hands at the start","unit":"$\\text{cm}$"},{"symbol":"$D$","meaning":"vertical travel (≥ 25)","unit":"$\\text{cm}$"},{"symbol":"$A$","meaning":"twisting angle","unit":"$^\\circ$"},{"symbol":"$FM, CM$","meaning":"frequency and coupling multipliers (tables)","unit":null}]'::jsonb, 'Lifting index = load ÷ RWL; above 1 means increased risk. Doubling the reach halves the limit.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Basic Occupational Safety & Health' AND t."subject" = 'ESAS' AND s."normKey" = 'ergonomics' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Basic Occupational Safety & Health' AND t."subject" = 'ESAS'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
