SELECT gen_random_uuid()::text, 'formula', '$T = \frac{8}{2^{(L - 90)/5}}$', 'Permissible Noise Exposure', '$T = \frac{8}{2^{(L - 90)/5}}\ \text{h};\qquad D = \sum\frac{C_i}{T_i} \le 1$', '$\text{h}$', 'How long a worker may be exposed to a noise level: 90 dBA for 8 hours, halved for every 5 dB more.', '[{"symbol":"$L$","meaning":"sound level","unit":"$\\text{dBA}$"},{"symbol":"$C_i$","meaning":"hours at each level","unit":"$\\text{h}$"},{"symbol":"$T_i$","meaning":"hours allowed at that level","unit":"$\\text{h}$"}]'::jsonb, '95 dBA: 4 h; 100 dBA: 2 h; 115 dBA: 15 min. A mixed day is within limits if the dose D ≤ 1 (100%).', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Basic Occupational Safety & Health' AND t."subject" = 'ESAS' AND s."normKey" = 'industrial hygiene' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Basic Occupational Safety & Health' AND t."subject" = 'ESAS'
