SELECT gen_random_uuid()::text, 'formula', '$TWA = \frac{\sum C_it_i}{8}$', 'Time-Weighted Average Exposure', '$TWA = \frac{\sum C_i t_i}{8\ \text{h}}$', '$\text{ppm}$', 'A worker''s average exposure to an airborne substance over an 8-hour shift, compared with its threshold limit value.', '[{"symbol":"$C_i$","meaning":"concentration during period i","unit":"$\\text{ppm}$"},{"symbol":"$t_i$","meaning":"length of period i","unit":"$\\text{h}$"}]'::jsonb, 'Unexposed time counts as zero in the sum; still divide by 8.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Basic Occupational Safety & Health' AND t."subject" = 'ESAS' AND s."normKey" = 'industrial hygiene' AND s."active"), NULL, false, 'PENDING', now(), now()
