SELECT gen_random_uuid()::text, 'formula', '$WBGT = 0.7T_{nwb} + 0.2T_g + 0.1T_{db}$', 'Wet Bulb Globe Temperature', '$\text{outdoors (sun): } WBGT = 0.7T_{nwb} + 0.2T_g + 0.1T_{db};\qquad \text{indoors: } 0.7T_{nwb} + 0.3T_g$', '$^\circ\text{C}$', 'The heat-stress index that sets work-rest cycles in hot workplaces.', '[{"symbol":"$T_{nwb}$","meaning":"natural wet-bulb temperature","unit":"$^\\circ\\text{C}$"},{"symbol":"$T_g$","meaning":"globe temperature","unit":"$^\\circ\\text{C}$"},{"symbol":"$T_{db}$","meaning":"dry-bulb (air) temperature","unit":"$^\\circ\\text{C}$"}]'::jsonb, 'Humidity dominates: the wet bulb carries 70% of the weight.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Basic Occupational Safety & Health' AND t."subject" = 'ESAS' AND s."normKey" = 'industrial hygiene' AND s."active"), NULL, false, 'PENDING', now(), now()
