SELECT gen_random_uuid()::text, 'formula', '$FR = \frac{N \times 10^6}{H}$', 'Frequency and Severity Rates', '$FR = \frac{N \times 1\,000\,000}{H},\qquad SR = \frac{D \times 1\,000\,000}{H}$', NULL, 'Injury statistics per million employee-hours, as the OSHS (Rule 1050) requires in the annual exposure data report.', '[{"symbol":"$N$","meaning":"disabling injuries","unit":null},{"symbol":"$D$","meaning":"days lost or charged","unit":null},{"symbol":"$H$","meaning":"total employee-hours worked","unit":"$\\text{h}$"}]'::jsonb, 'SR ÷ FR is the average days lost per injury. US OSHA rates use 200 000 hours instead. The report is due by January 30.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Basic Occupational Safety & Health' AND t."subject" = 'ESAS' AND s."normKey" = 'reporting and records' AND s."active"), NULL, true, 'PENDING', now(), now()
